from pathlib import Path
from docx import Document
from docx.shared import Inches, Pt, RGBColor
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

ROOT=Path(__file__).resolve().parent
doc=Document()
s=doc.sections[0]; s.top_margin=s.bottom_margin=Inches(.65); s.left_margin=s.right_margin=Inches(.75)
normal=doc.styles['Normal']; normal.font.name='Arial'; normal.font.size=Pt(10)
normal.paragraph_format.space_after=Pt(5)
for name in ['Title','Heading 1','Heading 2']:
    doc.styles[name].font.name='Arial'; doc.styles[name].font.color.rgb=RGBColor(0,0,0)
doc.styles['Title'].font.size=Pt(20)
doc.styles['Heading 1'].font.size=Pt(14)
doc.styles['Heading 2'].font.size=Pt(10.5)
foot=s.footer.paragraphs[0]; foot.alignment=2
foot.add_run('Form 4B proposed answers | ')
field=OxmlElement('w:fldSimple'); field.set(qn('w:instr'),'PAGE'); foot._p.append(field)

doc.add_paragraph('Form 4B Informed Consent Assessment', 'Title')
doc.add_paragraph('Proposed answers for the Academic Early Warning System study','Subtitle')
doc.add_paragraph('Study protocol title: AI-Powered Predictive Analytics for an Academic Early Warning System')
doc.add_paragraph('Researchers: Kendrick O. Amparado; Christian Dave Estrañero Pombo; Ian Carlo B. Quimbo; Kent Ian C. Seridon.')
doc.add_paragraph('Institution: Information Technology Department, College of Technologies, Bukidnon State University. Adviser: Czarissa A. Navidad.')
doc.add_paragraph('Principal investigator: Confirm the designated PI. Reference number: To be issued upon RGAO registration. Code: To be issued by BukSU REC. Submission date: To be supplied.')
doc.add_paragraph('How to use these answers','Heading 1')
doc.add_paragraph('This response sheet follows all 33 elements in the supplied Form 4B. It provides study-specific proposed consent content. No standalone informed consent form (ICF) was identified in the materials reviewed, so an applicable element cannot yet be certified YES or assigned an actual ICF page and paragraph. For applicable items, leave YES unmarked until the finalized ICF contains the statement and its location is verified. N/A entries below are provisional applicability judgments for this nonclinical study.')
doc.add_paragraph('All proposed safeguards and commitments require agreement by the research team and inclusion in the approved protocol and ICF. Bracketed details require confirmation. Reviewer comments, recommended action, approval, reviewer names, and signatures remain for BukSU REC; no ethics approval is asserted here.')
doc.add_paragraph('Analysis that determines the answers','Heading 1')
doc.add_paragraph('The study develops and evaluates AEWS through Design Science Research, stakeholder interviews, usability testing, and predictive-model evaluation. The software combines grades, attendance and needs assessments to support risk classification, referrals and human support decisions. Needs-assessment inputs include financial, family, physical-health and mental-health concerns, making privacy, distress and stigma material risks.')
doc.add_paragraph('The manuscript proposes approximately 15 stakeholder interviews of 45–60 minutes each. The 1,000 model-ready student records describe the training dataset, not the number of people recruited for interviews or usability testing. Confirm the number of unique record subjects and all prospective participant groups separately.')
doc.add_paragraph('Resolve a protocol inconsistency before submission: the Scope and Delimitations excludes extensive retention-outcome measurement, but Research Design proposes a historical-control comparison of retention and performance. The answers below follow the implemented development and evaluation scope; any retained comparison needs explicit procedures and record-use authorization.')

items=[
('Research statement','Pending ICF','You are invited to participate in a research capstone study on the development and evaluation of the Academic Early Warning System (AEWS) at Bukidnon State University. Participation in research must be distinguished from routine academic monitoring and support services.'),
('Purpose of the study','Pending ICF','The study aims to develop and evaluate a web system that uses academic records, attendance and needs-assessment information to identify possible academic difficulty and support timely AMU referrals. It evaluates functionality, predictive performance, usability and institutional relevance. Improved grades, retention or individual outcomes are not guaranteed.'),
('Treatments and random assignment','N/A','The implemented study does not involve clinical treatments or random assignment to treatment groups. The manuscript proposes historical controls in one section; historical comparison is not random assignment. If that component remains, explain the groups and record access in the protocol and ICF.'),
('Study procedures including invasive procedures','Pending ICF','Stakeholder activities described in the manuscript include semi-structured interviews, system evaluation and a System Usability Scale questionnaire with feedback. Academic, attendance and needs-assessment records are linked by Student_ID for model development and prediction. State which activities apply to each participant group and whether interviews or discussions are recorded. No invasive procedures or biological sampling are described.'),
('Participant responsibilities','Pending ICF','Participants will complete only the agreed interview, evaluation tasks or questionnaire and give feedback based on their experience. Authorized staff should use approved test records and protect account credentials. Students who consent to research use of their records or responses must be told exactly what will be used. Explain whether sensitive questions may be skipped without losing access to support.'),
('Duration of participation','Pending ICF','The manuscript specifies 45–60 minutes for each requirements interview. It does not establish the duration or number of usability sessions, questionnaires, focus groups or student follow-ups. Insert the verified schedule for each group; do not use the software development sprint schedule as the duration of participant involvement.'),
('Approximate number of participants','Pending ICF','Approximately 15 purposively sampled stakeholder interviews are proposed. The total number of unique interviewees, usability evaluators, focus-group members and student participants remains to be confirmed. Separately disclose the number and source of student records used. The 1,000 training records cannot be presented as 1,000 consenting research participants without verification.'),
('Experimental aspects','Pending ICF','AEWS and its XGBoost-based risk predictions are being developed and evaluated. Predictions may be inaccurate or biased and do not establish a clinical diagnosis or a guaranteed academic outcome. The manuscript requires designated staff to review AI risk flags before a formal intervention. Distinguish automatic referral flags from human decisions on support.'),
('Foreseeable risks and inconvenience','Pending ICF','Risks include time burden, discomfort discussing academic or personal difficulties, unauthorized disclosure, stigma from a risk label, inaccurate predictions and inappropriate referrals. Needs assessments can reveal financial, family, physical-health and mental-health concerns. Explain safeguards, optional questions, withdrawal and the response to distress or disclosure incidents. No pregnancy-specific procedure is described, but information disclosures may also affect family members.'),
('Placebo risks','N/A','No placebo, medication or clinical treatment is described.'),
('Expected benefits to participants','Pending ICF','Participants may gain experience with AEWS or contribute feedback that improves academic monitoring. Students may benefit from more timely human review and referral where ordinary services are available. Participation may provide no direct benefit; the system does not guarantee improved grades, continued enrollment or receipt of a particular service.'),
('Benefits to the community and knowledge','Pending ICF','Findings may help BukSU improve academic monitoring, AMU referral workflows and the design of educational decision-support tools. The research can contribute evidence on software usability and academic-risk prediction. Broader reductions in dropout or improved retention remain potential benefits rather than outcomes established by this study.'),
('Post-study access to a proven product or intervention','N/A for the specified clinical provision','No proven clinical study product or intervention is described. For software transparency, nevertheless explain that continued AEWS access depends on university authorization, maintenance and deployment decisions. Do not promise permanent access or describe the prototype as proven safe and effective.'),
('Alternative procedures or treatment','Pending ICF','For this nonclinical study, the relevant alternative is declining research participation while continuing ordinary university academic advising, mentoring and available support services. State that existing services remain available under their usual eligibility rules. Confirm the specific services and access route; do not promise a clinical treatment.'),
('Treatment insurance or compensation for study injury','Pending ICF','No study-specific insurance, treatment entitlement or injury-compensation arrangement is documented. The team must confirm and disclose the actual policy, including who handles distress or other research-related harm and where assistance can be sought. A noninvasive study can still cause informational or psychological harm; do not simply mark this N/A or promise coverage.'),
('Payments or material incentives','Pending ICF','Payment and reimbursement arrangements are not established in the manuscript. Confirm whether there is no payment or whether an incentive is offered; if offered, state the exact type, amount, timing and treatment of withdrawal. Do not claim that participants will be paid or that no payment exists without confirmation.'),
('Compensation for disability or death','Pending ICF','No arrangement for disability or death arising from research-related injury is documented. Obtain the institution’s actual policy and state whether any study-specific compensation exists. Do not promise compensation, insert a waiver of participant rights, or infer an insurance entitlement from the study’s nonclinical nature.'),
('Participant expenses','Pending ICF','Confirm whether participation requires transport, mobile data, internet access, printing or personal-device use, and whether costs will be reimbursed. Disclose foreseeable costs and any university-provided facilities. No verified amount or no-cost arrangement is available in the reviewed study.'),
('Voluntary participation and withdrawal','Pending ICF','Participation is voluntary. Refusal or withdrawal must not affect grades, employment, standing or ordinary support entitlements. Explain the withdrawal contact and deadline for removing identifiable research data, including limits once data are irreversibly anonymized or results aggregated. Distinguish withdrawal from research from retention of official university records under institutional rules.'),
('Access to medical records for clinical-trial verification','N/A','This is not a clinical trial and no access to clinical medical records is described. Self-reported health concerns in a needs assessment still require protection. Separately disclose any authorized REC review of research records, the purpose and confidentiality limits; do not use this item to authorize unrestricted access to student records.'),
('Confidentiality and its limitations','Pending ICF','The ICF must identify the records collected, research purpose, authorized recipients, storage location, retention period, deletion method and publication safeguards. Propose coded research extracts, a separately protected linkage key and aggregate reporting. Explain that confidentiality cannot be absolute and describe any approved disclosure limits. The code contains public student-data routes and a header-based authentication fallback, so unrestricted claims of secure or confidential access are not supported.'),
('Genetic tests and familial genetic information','N/A','No genetic testing or familial genetic-information collection is described. Ordinary family concerns in a needs assessment are not genetic testing.'),
('Secondary use of medical records and biological specimens','N/A for the specified materials','No clinical medical records or biological specimens are described. Separately disclose research use of academic records and health-related self-reports, including whether model training, future retraining or sharing is permitted. Obtain the required permission or approved waiver; routine possession of student records does not establish research authorization.'),
('Storage or destruction of biological specimens','N/A','No biological specimens are collected or stored. For digital research records, the team must still specify an approved retention period, storage location, access restrictions, deletion process, backup handling and any limits on removing data from completed analyses or trained models.'),
('Commercial products from biological specimens','N/A','No biological specimens or specimen-derived commercial products are involved. If AEWS software or research data may later be commercialized, disclose that separately; do not infer that there is no software commercialization plan merely because this biological-specimen item is inapplicable.'),
('New information affecting willingness to continue','Pending ICF','Proposed statement: We will inform you promptly of significant new information that may affect your willingness to continue, including material changes in procedures, data use, privacy risk or findings about prediction reliability. Explain how participants will be contacted and whether renewed consent will be sought.'),
('Participant access to study results','Pending ICF','Propose providing an understandable summary of overall findings through the research team after completion. Confirm the request contact, delivery method and expected availability. Individual academic-risk displays are not equivalent to the research results and must be explained separately without exposing other students’ information.'),
('Participant access to personal records','Pending ICF','Explain how participants can request access to or correction of their own research information and academic-source errors through the designated researcher or university office. State identity-verification requirements and any justified limits protecting others. Research withdrawal does not automatically erase official academic records. A working correction or access process has not been verified.'),
('Termination of participation','Pending ICF','Specify approved reasons such as participant request, ineligibility, inability to consent, unacceptable privacy or safety risk, or suspension of the study by the institution or REC. Explain what happens to existing data and support access. A high-risk prediction alone should not be presented as a reason for excluding or penalizing a participant.'),
('Sponsor affiliation and funding','Pending ICF','The researchers are BS Information Technology capstone students in the Information Technology Department, College of Technologies, Bukidnon State University. The manuscript names Czarissa A. Navidad as adviser. Funding, sponsorship and relevant conflicts of interest are not established; confirm them before stating that the study is self-funded or externally sponsored.'),
('Investigator and healthcare-provider roles','Pending ICF','The named researchers are IT capstone investigators; no healthcare-provider role is documented for them. State their actual role and distinguish research duties from academic evaluation or mentoring roles. Where a recruiter also supervises, grades or supports participants, explain safeguards against pressure to participate.'),
('Research-team and harm contacts','Pending ICF','Insert the confirmed principal investigator’s name, institutional email and phone number, plus the adviser or designated contact for research-related concerns or harm. Identify how urgent distress will be referred to an appropriate university service. Do not use placeholder emails or invent contact information.'),
('REC approval and rights or complaint contacts','Pending ICF and REC confirmation','Do not state that BukSU REC has approved the study until written approval is issued. Once approved, insert the verified approval reference/date and REC chair’s name, address, email, telephone and mobile contact as required by the form. Provide an independent route for questions about rights, grievances or complaints.')
]
